160→// ─── Action ───────────────────────────────────────────────────────────────────
161→
162→export const action = async ({ request }: ActionFunctionArgs): Promise<
163→  | { error: string }
164→  | { success: boolean; message: string }
165→  | null
166→> => {
167→  const { session, billing } = await authenticate.admin(request);
168→  const shop = session.shop;
169→  const formData = await request.formData();
170→  const intent = String(formData.get("intent"));
171→
172→  if (intent === "subscribe") {
173→    const plan = String(formData.get("plan"));
174→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
175→    try {
176→      /* eslint-disable @typescript-eslint/no-explicit-any */
177→      await billing.request({
178→        plan: plan as any,
179→        isTest: process.env.NODE_ENV !== "production",
180→        returnUrl,
181→      });
182→      /* eslint-enable @typescript-eslint/no-explicit-any */
183→      return null;
184→    } catch (error) {
185→      if (error instanceof Response) throw error;
186→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
187→      const details = errorData?.map((e) => e.message).join(", ");
188→      const message = details || (error instanceof Error ? error.message : String(error));
189→
190→      if (message.includes("Custom apps cannot use the Billing API")) {
191→        return {
192→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
193→        };
194→      }
195→      return {
196→        error: `Failed to initiate subscription: ${message}`,
197→      };
198→    }
199→  }
200→
201→  if (intent === "test-set-plan") {
202→    if (shop !== "zip-code-checker.myshopify.com") {
203→      return { error: "This action is only available for the admin store." };
204→    }
205→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
206→    const validTiers = ["free", "starter", "pro", "ultimate"];
207→    if (!validTiers.includes(tier)) {
208→      return { error: `Invalid plan tier: ${tier}` };
209→    }
210→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
211→    await db.subscription.upsert({
212→      where: { shop },
213→      create: { shop, planId, billingInterval: "monthly", status: "active" },
214→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
215→    });
216→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
217→  }
218→
219→  if (intent === "cancel") {
220→    try {
221→      const sub = await getShopSubscription(shop);
222→      if (sub.shopifySubscriptionId) {
223→        await billing.cancel({
224→          subscriptionId: sub.shopifySubscriptionId,
225→          isTest: process.env.NODE_ENV !== "production",
226→          prorate: true,
227→        });
228→      }
229→      await cancelShopSubscription(shop);
230→      return {
231→        success: true,
232→        message: "Subscription cancelled. You are now on the Free plan.",
233→      };
234→    } catch {
235→      return { error: "Failed to cancel subscription. Please try again." };
236→    }
237→  }
238→
239→  return null;
240→};
