288→
289→function PlanCard({
290→  plan,
291→  isAnnual,
292→  currentTier,
293→  onSubscribe,
294→  loadingPlan,
295→}: PlanCardProps) {
296→  const isCurrent = currentTier === plan.id;
297→  const isBestValue = "bestValue" in plan && plan.bestValue;
298→  const isCurrentPaid = currentTier !== "free";
299→
300→  const isUpgrade =
301→    !isCurrent &&
302→    plan.id !== "free" &&
303→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
304→
305→  const isDowngrade =
306→    !isCurrent &&
307→    plan.id !== "free" &&
308→    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);
309→
310→  const shopifyPlan = isAnnual
311→    ? plan.shopifyPlanAnnual
312→    : plan.shopifyPlanMonthly;
313→
314→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
315→
316→  let buttonContent = "Start free trial";
317→  let buttonVariant: "primary" | "secondary" = "primary";
318→
319→  if (isCurrent) {
320→    buttonContent = "Current plan";
321→    buttonVariant = "secondary";
322→  } else if (isUpgrade) {
323→    buttonContent = `Upgrade to ${plan.name}`;
324→    buttonVariant = "primary";
325→  } else if (isDowngrade) {
326→    buttonContent = `Switch to ${plan.name}`;
327→    buttonVariant = "secondary";
328→  } else if (!isCurrent && isCurrentPaid) {
329→    buttonContent = `Switch to ${plan.name}`;
330→    buttonVariant = "secondary";
331→  }
332→
333→  const handleClick = () => {
334→    if (shopifyPlan) {
335→      onSubscribe(shopifyPlan);
336→    }
337→  };
338→
339→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
340→
341→  return (
342→    <Box
343→      background="bg-surface"
344→      borderWidth="025"
345→      borderColor="border"
346→      borderRadius="300"
347→      padding="0"
348→      overflowX="hidden"
349→      overflowY="hidden"
350→    >
351→      {/* Top accent — thin bar for recommended plan, transparent spacer for others */}
352→      <Box
353→        background={isBestValue && !isCurrent ? "bg-fill-info" : undefined}
354→        minHeight="4px"
355→      />
356→
357→      <Box padding="500">
358→        <BlockStack gap="400">
359→
360→          {/* Plan name + badges */}
361→          <BlockStack gap="100">
362→            <InlineStack gap="200" blockAlign="center" wrap={false}>
363→              <Text as="h3" variant="headingLg" fontWeight="bold">
364→                {plan.name}
365→              </Text>
366→              {isCurrent && <Badge tone="success">Active</Badge>}
367→              {isBestValue && !isCurrent && <Badge tone="info-strong">Most popular</Badge>}
368→            </InlineStack>
369→            <Text as="p" variant="bodyMd" tone="subdued">
370→              {plan.description}
371→            </Text>
372→          </BlockStack>
373→
374→          {/* Price */}
375→          <BlockStack gap="050">
376→            <InlineStack gap="100" blockAlign="baseline" wrap={false}>
377→              <Text as="p" variant="heading2xl" fontWeight="bold">
378→                ${displayPrice}
379→              </Text>
380→              <Text as="p" variant="bodyMd" tone="subdued">
381→                /mo
382→              </Text>
383→            </InlineStack>
384→            <Text as="p" variant="bodyMd" tone="subdued">
385→              {isAnnual
386→                ? `$${plan.annualPrice} billed annually`
387→                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
388→            </Text>
389→          </BlockStack>
390→
391→          {/* CTA */}
392→          <Button
393→            variant={buttonVariant}
394→            onClick={handleClick}
395→            disabled={isCurrent}
396→            loading={isThisLoading}
397→            fullWidth
398→            size="large"
399→          >
400→            {buttonContent}
401→          </Button>
402→
403→          <Divider />
404→
405→          {/* Features */}
406→          <BlockStack gap="300">
407→            {plan.features.map((f) => (
408→              <PlanFeature key={f} feature={f} />
409→            ))}
410→          </BlockStack>
411→
412→        </BlockStack>
413→      </Box>
414→    </Box>
415→  );
416→}
