507→                  <BlockStack gap="050">
508→                    <InlineStack gap="200" blockAlign="center" wrap={false}>
509→                      <Text as="h3" variant="headingLg" fontWeight="bold">
510→                        Free
511→                      </Text>
512→                      {isFreeTier && <Badge tone="success">Active</Badge>}
513→                    </InlineStack>
514→                    <Text as="p" variant="bodyMd" tone="subdued">
