516→                    </Text>
517→                  </BlockStack>
518→
519→                  <InlineStack gap="100" blockAlign="baseline" wrap={false}>
520→                    <Text as="p" variant="heading2xl" fontWeight="bold">
521→                      $0
522→                    </Text>
523→                    <Text as="p" variant="bodyMd" tone="subdued">
524→                      forever
525→                    </Text>
526→                  </InlineStack>
527→
528→                  <Box minWidth="180px">
529→                    {isFreeTier ? (
530→                      <Button variant="secondary" disabled fullWidth size="large">
531→                        Current plan
532→                      </Button>
533→                    ) : (
534→                      <Button
